import type { Metadata } from "next";
import { site } from "@/lib/site";

// Generated by app/opengraph-image.tsx. Listed explicitly because a route's
// `openGraph` object replaces (rather than merges with) the inherited one.
const ogImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "NexIon Labs: high-performance websites built by senior developers",
};

/**
 * Per-route metadata with canonical, Open Graph and Twitter tags.
 * The OG image comes from app/opengraph-image.tsx and is inherited automatically.
 */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title?: string;
  description: string;
  path: string;
}): Metadata {
  const fullTitle = title ? `${title} | ${site.name}` : undefined;
  return {
    ...(title ? { title } : {}),
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "en_AU",
      siteName: site.name,
      url: path,
      ...(fullTitle ? { title: fullTitle } : {}),
      description,
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      ...(fullTitle ? { title: fullTitle } : {}),
      description,
      images: [ogImage.url],
    },
  };
}
